    if code in GROUPS:
     en,ru=GROUPS[code];gid=t['id']+'-'+re.sub(r'[^a-z0-9]+','-',en.lower());gname=bi(ru,en);desc=row[0]['en'];desc=re.sub(r'\s*\(?9961\s*$','',desc).strip(' .…');desc=desc.replace('6/B','6/Box')if desc.endswith('6/B')else desc;desc=desc.replace('6/Bo','6/Box')if desc.endswith('6/Bo')else desc
